insert into public.learning_cards (lesson_id, position, title, blocks) values ('f917d88f-e669-50d0-bd4c-d557d86d3b56', 1, 'Link, pas Zelda', '[{"type":"text","text":"The Legend of Zelda débute en 1986. Piège classique : le héros en tunique verte s’appelle Link. Zelda est la princesse."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('f917d88f-e669-50d0-bd4c-d557d86d3b56', 2, 'Un dernier jeu qui n’en finit pas', '[{"type":"text","text":"Le premier Final Fantasy sort en 1987 chez Square. Selon la légende, son créateur pensait que ce serait son dernier jeu. La série compte aujourd’hui plus de quinze épisodes principaux."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('f917d88f-e669-50d0-bd4c-d557d86d3b56', 3, 'L’infiltration', '[{"type":"text","text":"En 1987, Hideo Kojima crée Metal Gear : le but n’est plus de tirer partout, mais de passer inaperçu."}]'::jsonb);
