insert into public.learning_cards (lesson_id, position, title, blocks) values ('a00a5c3f-7243-5660-94a7-4676fdb98527', 1, 'Made in Scotland', '[{"type":"text","text":"Le premier GTA sort en 1997. Il est développé en Écosse par DMA Design, devenu Rockstar North. GTA V, en 2013, devient l’un des produits culturels les plus rentables de l’histoire."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('a00a5c3f-7243-5660-94a7-4676fdb98527', 2, 'Des blocs et des milliards', '[{"type":"keyfigure","value":"2,5 Md$","label":"Prix du rachat de Minecraft par Microsoft, en 2014"},{"type":"text","text":"Créé par le Suédois Markus « Notch » Persson, Minecraft est le jeu le plus vendu de l’histoire."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('a00a5c3f-7243-5660-94a7-4676fdb98527', 3, 'Battle Royale', '[{"type":"text","text":"En 2017, Epic Games lance le mode Battle Royale de Fortnite : cent joueurs, une seule victoire."}]'::jsonb);
